py -V:3.12 -I -B -c "import json,pathlib; R=pathlib.Path('.');
def j(p): return json.loads((R/p).read_text(encoding='utf-8'))
for par in ['Nntp','Nctp','Nrtp','NTRv','NWGv','NSps','Nfmp','NCro']:
 d=j(f'scratch/t49/out/fields_{par}.json'); print('PARENT',par,'L3',d['L3'],'L4',d['L4']);
 for c,x in d['fields'].items(): print(' ',c,'keys=',','.join(x),'grade=',x.get('grade'),'status=',x.get('status'),'offset=',x.get('accepted_item_offset'),'width=',x.get('width'),'mask=',x.get('mask'),'reason=',x.get('reason'))
d=j('scratch/t49/out/discovery_t9_wire.json');
for k,v in d.items():
 if k in ('trials','targets','binding','owner_fixup','status','L3','held','editor_sha256','provenance'):
  if isinstance(v,dict):
   print('DISC',k,'keys',list(v))
   if k=='binding': print(' BIND',v)
   if k=='targets': print(' TARGETS',v)
   if k=='trials':
    for sk,sv in v.items(): print(' TRIAL',sk, (sv if isinstance(sv,(str,int,float,bool)) else (list(sv) if isinstance(sv,dict) else len(sv))))
  else: print('DISC',k,v)
for p in ['scratch/t49/out/cursor_t9_client.json','scratch/t49/out/cursor_t9_server.json','scratch/t51/out/cursor_table_9_client.json','scratch/t51/out/cursor_table_9_server.json','scratch/t51/out/cursor_table_10_server.json','scratch/t47/out/cursor_nation_tax.json']:
 d=j(p); print('CURSOR',p,'keys',list(d));
 for k in ['mode','payload_len','payload_sha256','count','stride','rows','row_count','row_sum','footer_hex','row_length_range','item_coordinates','server','client']:
  if k in d:
   v=d[k]
   if isinstance(v,list): print(' ',k,len(v),'first=',v[0] if v else None,'last=',v[-1] if v else None)
   elif isinstance(v,dict): print(' ',k,'keys',list(v),'mini',{a:b for a,b in v.items() if not isinstance(b,(dict,list))})
   else: print(' ',k,v)
"

